const LIMITE = 600;
const MIN_MERGE = 45;

function limpar(t) {
  return t
    .replace(/```[\s\S]*?```/g, '')
    .replace(/\*\*(.*?)\*\*/g, '$1')
    .replace(/\*(.*?)\*/g, '$1')
    .replace(/__(.*?)__/g, '$1')
    .replace(/_(.*?)_/g, '$1')
    .replace(/~~(.*?)~~/g, '$1')
    .replace(/^#{1,6}\s*/gm, '')
    .replace(/^\s*[-*+]\s+/gm, '')
    .replace(/\s*—\s*/g, ', ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/[ \t]+/g, ' ')
    .trim();
}

function ehLista(bloco) {
  const linhas = bloco.split('\n').filter(l => l.trim());
  return linhas.length >= 3 && linhas.every(l => l.trim().length < 90);
}

const bruto = $json.output;

if (!bruto || typeof bruto !== 'string' || !bruto.trim()) {
  return [];
}

const RE_SAUDACAO = /^(ol[áa]|oi)[,!]?\s*(bom dia|boa tarde|boa noite)[!.]?\s*(\p{Extended_Pictographic}+)?\s*/iu;
let saudacao = null;
let corpo = bruto;
const m = bruto.match(RE_SAUDACAO);
if (m && m[0].trim().length < 40) {
  saudacao = m[0].trim();
  corpo = bruto.slice(m[0].length).trim();
  if (!corpo) { corpo = ''; }
}

const blocos = corpo.split(/\n\s*\n/).map(b => b.trim()).filter(Boolean);

const partes = [];
for (const bloco of blocos) {
  if (ehLista(bloco)) {
    partes.push(limpar(bloco.replace(/\n/g, '\n')));
    continue;
  }
  const texto = limpar(bloco.replace(/\n/g, ' '));
  if (!texto) continue;

  if (texto.length <= LIMITE) {
    partes.push(texto);
  } else {
    const frases = texto.match(/[^.!?]+[.!?]+|\S+$/g) || [texto];
    let atual = '';
    for (const f of frases) {
      if ((atual + ' ' + f).trim().length > LIMITE && atual) {
        partes.push(atual.trim());
        atual = f;
      } else {
        atual = (atual + ' ' + f).trim();
      }
    }
    if (atual.trim()) partes.push(atual.trim());
  }
}

const finais = [];
for (let i = 0; i < partes.length; i++) {
  const p = partes[i];
  const curto = p.length < MIN_MERGE && !p.endsWith('?');
  const grudavel = curto && /\.\s*$/.test(p);
  if (grudavel && finais.length) {
    finais[finais.length - 1] += ' ' + p;
  } else if (grudavel && !finais.length && partes[i + 1]) {
    partes[i + 1] = p + ' ' + partes[i + 1];   // gruda no proximo
  } else {
    finais.push(p);
  }
}

const saida = finais.filter(m => m && m.trim().length > 0);

if (saudacao) saida.unshift(saudacao);

if (!saida.length) {
  return [];
}

return saida.map(m => ({ json: { output: m } }));

const isPhone = (j) => typeof j === 'string' && j.endsWith('@s.whatsapp.net');
const out = [];

for (const item of $input.all()) {
  const raw = item.json;
  const key = (raw && raw.body && raw.body.data && raw.body.data.key) || {};
  const remoteJid = key.remoteJid || '';
  let telefone = remoteJid;
  let metodo = 'remoteJid';

  if (!isPhone(remoteJid) && remoteJid.endsWith('@lid')) {
    if (isPhone(key.remoteJidAlt)) {
      telefone = key.remoteJidAlt;
      metodo = 'remoteJidAlt';
    } else if (isPhone(key.senderPn)) {
      telefone = key.senderPn;
      metodo = 'senderPn';
    } else {
      const serverUrl = raw && raw.body && raw.body.server_url;
      const instance  = raw && raw.body && raw.body.instance;
      const apikey    = raw && raw.body && raw.body.apikey;
      metodo = 'findMessages';
      try {
        const resp = await this.helpers.httpRequest({
          method: 'POST',
          url: serverUrl + '/chat/findMessages/' + encodeURIComponent(instance),
          headers: { apikey: apikey, 'Content-Type': 'application/json' },
          body: { where: { key: { remoteJid: remoteJid } } },
          json: true,
        });
        const records = (resp && resp.messages && resp.messages.records) || [];
        let achou = null;
        for (const r of records) {
          const k = (r && r.key) || {};
          if (isPhone(k.remoteJidAlt)) { achou = k.remoteJidAlt; break; }
          if (isPhone(k.remoteJid))    { achou = k.remoteJid;    break; }
        }
        if (achou) { telefone = achou; }
        else { metodo = 'findMessages_sem_vinculo'; }
      } catch (e) {
        metodo = 'findMessages_erro';
      }
    }
  }

  out.push({
    json: Object.assign({}, raw, {
      telefoneResolvido: telefone,
      lidOriginal: remoteJid,
      metodoResolucao: metodo,
    })
  });
}

return out;
